import { PrismaPg } from '@prisma/adapter-pg';
import { PrismaClient } from '../../prisma/generated/client';
import { afterAll } from 'vitest';
import { setupPrismaTestDb, setupTestGlobals } from '@lowerdeck/testing-tools';
import { provider } from '../providers/aws-lambda/provider';

setupTestGlobals({ nodeEnv: 'test' });

const db = await setupPrismaTestDb<PrismaClient>({
  guard: 'function-bay-test',
  prismaClientFactory: url => new PrismaClient({ adapter: new PrismaPg({ connectionString: url }) })
});

afterAll(async () => {
  await db.disconnect();
});

export const testDb: PrismaClient = db.client;

// Clean database and re-seed the provider with the same oid that production code expects
export const cleanDatabase = async () => {
  await db.clean();
  // Re-create provider with the cached oid from production code
  await testDb.provider.upsert({
    where: { identifier: provider.identifier },
    create: {
      oid: provider.oid,
      id: provider.id,
      identifier: provider.identifier,
      name: provider.name
    },
    update: {}
  });
};

import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
  FunctionDeploymentStatus,
  FunctionDeploymentStepStatus
} from '../../../prisma/generated/client';
import { functionBayClient } from '../../test/client';
import { fixtures } from '../../test/fixtures';
import { cleanDatabase, testDb } from '../../test/setup';

const buildQueueMocks = vi.hoisted(() => ({
  add: vi.fn().mockResolvedValue({ id: 'test-job-id' })
}));

vi.mock('../../queues/build', () => ({
  startBuildQueue: {
    add: buildQueueMocks.add
  }
}));

describe('functionDeployment:create E2E', () => {
  const f = fixtures(testDb);

  beforeEach(async () => {
    await cleanDatabase();
    buildQueueMocks.add.mockReset();
  });

  it('creates a new deployment', async () => {
    const func = await f.function.withTenant();
    await f.runtime.nodejs22();

    const result = await functionBayClient.functionDeployment.create({
      tenantId: func.tenant.id,
      functionId: func.id,
      name: 'Production Deploy',
      runtime: { identifier: 'nodejs', version: '22.x' },
      config: {
        memorySizeMb: 256,
        timeoutSeconds: 30
      },
      env: { NODE_ENV: 'production' },
      files: [
        {
          filename: 'index.js',
          content: 'exports.handler = async () => ({ statusCode: 200 })'
        }
      ]
    });

    expect(result).toMatchObject({
      id: expect.any(String),
      name: 'Production Deploy',
      status: FunctionDeploymentStatus.pending,
      createdAt: expect.any(Date)
    });
  });

  it('creates deployment with base64 encoded files', async () => {
    const func = await f.function.withTenant();
    await f.runtime.nodejs22();

    const result = await functionBayClient.functionDeployment.create({
      tenantId: func.tenant.id,
      functionId: func.id,
      name: 'Binary Deploy',
      runtime: { identifier: 'nodejs', version: '22.x' },
      config: { memorySizeMb: 128, timeoutSeconds: 10 },
      env: {},
      files: [
        {
          filename: 'index.js',
          content: Buffer.from('exports.handler = () => {}').toString('base64'),
          encoding: 'base64'
        }
      ]
    });

    expect(result.status).toBe(FunctionDeploymentStatus.pending);
  });
});

describe('functionDeployment:list E2E', () => {
  const f = fixtures(testDb);

  beforeEach(async () => {
    await cleanDatabase();
  });

  it('returns deployments for a function', async () => {
    const func = await f.function.withTenantAndRuntime();

    const deployments = await Promise.all([
      f.functionDeployment.default({
        functionOid: func.oid,
        runtimeOid: func.runtime!.oid,
        overrides: { status: FunctionDeploymentStatus.pending }
      }),
      f.functionDeployment.default({
        functionOid: func.oid,
        runtimeOid: func.runtime!.oid,
        overrides: { status: FunctionDeploymentStatus.succeeded }
      }),
      f.functionDeployment.default({
        functionOid: func.oid,
        runtimeOid: func.runtime!.oid,
        overrides: { status: FunctionDeploymentStatus.failed }
      })
    ]);

    const deploymentIds = deployments.map(deployment => deployment.id);

    const result = await functionBayClient.functionDeployment.list({
      tenantId: func.tenant.id,
      functionId: func.id,
      limit: 10
    });

    expect(result.items).toHaveLength(3);
    result.items.forEach(item => {
      expect(deploymentIds).toContain(item.id);
      expect(item.function.id).toBe(func.id);
    });
    const [presented] = result.items;
    expect(presented).toBeDefined();
    expect(presented).toMatchObject({
      id: expect.any(String),
      name: expect.any(String),
      status: expect.any(String),
      function: {
        id: func.id
      },
      runtime: {
        id: func.runtime!.id
      }
    });
    const statuses = result.items.map(item => item.status);
    expect(statuses).toContain(FunctionDeploymentStatus.pending);
    expect(statuses).toContain(FunctionDeploymentStatus.succeeded);
    expect(statuses).toContain(FunctionDeploymentStatus.failed);
  });
});

describe('functionDeployment:get E2E', () => {
  const f = fixtures(testDb);

  beforeEach(async () => {
    await cleanDatabase();
  });

  it('returns a deployment by ID', async () => {
    const deployment = await f.functionDeployment.succeeded();

    const result = await functionBayClient.functionDeployment.get({
      tenantId: deployment.function.tenant.id,
      functionId: deployment.function.id,
      functionDeploymentId: deployment.id
    });

    expect(result).toMatchObject({
      id: deployment.id,
      name: deployment.name,
      status: FunctionDeploymentStatus.succeeded
    });
  });

  it('returns failed deployment with error details', async () => {
    const deployment = await f.functionDeployment.failed({
      errorCode: 'BUILD_ERROR',
      errorMessage: 'Compilation failed'
    });

    const result = await functionBayClient.functionDeployment.get({
      tenantId: deployment.function.tenant.id,
      functionId: deployment.function.id,
      functionDeploymentId: deployment.id
    });

    expect(result).toMatchObject({
      status: FunctionDeploymentStatus.failed,
      error: {
        code: 'BUILD_ERROR',
        message: 'Compilation failed'
      }
    });
  });
});

describe('functionDeployment:getOutput E2E', () => {
  const f = fixtures(testDb);

  beforeEach(async () => {
    await cleanDatabase();
  });

  it('returns deployment steps as output', async () => {
    const deployment = await f.functionDeployment.succeeded();

    await f.functionDeploymentStep.succeeded({
      functionDeploymentOid: deployment.oid,
      output: '[1234567890, "Build completed successfully"]'
    });

    const result = await functionBayClient.functionDeployment.getOutput({
      tenantId: deployment.function.tenant.id,
      functionId: deployment.function.id,
      functionDeploymentId: deployment.id
    });

    expect(result).toBeInstanceOf(Array);
    expect(result.length).toBeGreaterThanOrEqual(1);
    expect(result[0]).toMatchObject({
      status: FunctionDeploymentStepStatus.succeeded,
      logs: expect.arrayContaining([
        expect.objectContaining({
          timestamp: 1234567890,
          message: 'Build completed successfully'
        })
      ])
    });
  });

  it('returns empty array for deployment with no steps', async () => {
    const deployment = await f.functionDeployment.pending();

    const result = await functionBayClient.functionDeployment.getOutput({
      tenantId: deployment.function.tenant.id,
      functionId: deployment.function.id,
      functionDeploymentId: deployment.id
    });

    expect(result).toEqual([]);
  });

  it('returns multiple steps in order', async () => {
    const deployment = await f.functionDeployment.succeeded();

    await f.functionDeploymentStep.succeeded({
      functionDeploymentOid: deployment.oid,
      output: '[1234567890, "Step 1 complete"]',
      overrides: { name: 'Build' }
    });
    await f.functionDeploymentStep.succeeded({
      functionDeploymentOid: deployment.oid,
      output: '[1234567891, "Step 2 complete"]',
      overrides: { name: 'Deploy' }
    });

    const result = await functionBayClient.functionDeployment.getOutput({
      tenantId: deployment.function.tenant.id,
      functionId: deployment.function.id,
      functionDeploymentId: deployment.id
    });

    expect(result.length).toBe(2);
  });
});

import { randomBytes } from 'crypto';
import type {
  PrismaClient,
  FunctionDeployment,
  Function as FunctionModel,
  Runtime,
  FunctionBundle,
  Tenant,
  Provider
} from '../../../prisma/generated/client';
import { FunctionDeploymentStatus } from '../../../prisma/generated/client';
import { getId } from '../../id';
import { defineFactory } from '@lowerdeck/testing-tools';
import { FunctionFixtures } from './functionFixtures';
import { FunctionBundleFixtures } from './functionBundleFixtures';
import { Encryption } from '@lowerdeck/encryption';
import {
  resolveEncryptedEnvironmentVariables,
  withoutEncryptedEnvOverrides
} from './helpers';

const testEncryption = new Encryption(process.env.ENCRYPTION_KEY || 'test-encryption-key-32-bytes-key');

export const FunctionDeploymentFixtures = (db: PrismaClient) => {
  const functionFixtures = FunctionFixtures(db);
  const bundleFixtures = FunctionBundleFixtures(db);

  const defaultDeployment = async (data: {
    functionOid: bigint;
    runtimeOid: bigint;
    functionBundleOid?: bigint;
    overrides?: Partial<FunctionDeployment>;
  }): Promise<FunctionDeployment> => {
    const { oid, id } = getId('functionDeployment');
    const identifier =
      data.overrides?.identifier ?? `deploy-${randomBytes(4).toString('hex')}`;

    const encryptedEnv = await resolveEncryptedEnvironmentVariables({
      overrides: data.overrides,
      encryption: testEncryption,
      entityId: id
    });

    const factory = defineFactory<FunctionDeployment>(
      {
        oid,
        id,
        status: data.overrides?.status ?? FunctionDeploymentStatus.pending,
        identifier,
        name: data.overrides?.name ?? `Deployment ${identifier}`,
        functionOid: data.functionOid,
        runtimeOid: data.runtimeOid,
        functionBundleOid: data.functionBundleOid ?? null,
        functionVersionOid: data.overrides?.functionVersionOid ?? null,
        forgeRunId: data.overrides?.forgeRunId ?? null,
        forgeWorkflowId: data.overrides?.forgeWorkflowId ?? null,
        encryptedEnvironmentVariables: encryptedEnv,
        configuration: data.overrides?.configuration ?? {
          memorySizeMb: 256,
          timeoutSeconds: 30
        },
        errorCode: data.overrides?.errorCode ?? null,
        errorMessage: data.overrides?.errorMessage ?? null
      } as FunctionDeployment,
      {
        persist: value => db.functionDeployment.create({ data: value })
      }
    );

    return factory.create(withoutEncryptedEnvOverrides(data.overrides));
  };

  const pending = async (data?: {
    tenantOverrides?: Partial<Tenant>;
    functionOverrides?: Partial<FunctionModel>;
    deploymentOverrides?: Partial<FunctionDeployment>;
  }): Promise<
    FunctionDeployment & {
      function: FunctionModel & { tenant: Tenant };
      runtime: Runtime & { provider: Provider };
    }
  > => {
    const func = await functionFixtures.withTenantAndRuntime({
      tenantOverrides: data?.tenantOverrides,
      functionOverrides: data?.functionOverrides
    });

    const deployment = await defaultDeployment({
      functionOid: func.oid,
      runtimeOid: func.runtime!.oid,
      overrides: {
        status: FunctionDeploymentStatus.pending,
        ...data?.deploymentOverrides
      }
    });

    return db.functionDeployment.findUniqueOrThrow({
      where: { oid: deployment.oid },
      include: {
        function: { include: { tenant: true } },
        runtime: { include: { provider: true } }
      }
    }) as Promise<
      FunctionDeployment & {
        function: FunctionModel & { tenant: Tenant };
        runtime: Runtime & { provider: Provider };
      }
    >;
  };

  const succeeded = async (data?: {
    tenantOverrides?: Partial<Tenant>;
    functionOverrides?: Partial<FunctionModel>;
    deploymentOverrides?: Partial<FunctionDeployment>;
    bundleOverrides?: Partial<FunctionBundle>;
  }): Promise<
    FunctionDeployment & {
      function: FunctionModel & { tenant: Tenant };
      runtime: Runtime & { provider: Provider };
      functionBundle: FunctionBundle;
    }
  > => {
    const func = await functionFixtures.withTenantAndRuntime({
      tenantOverrides: data?.tenantOverrides,
      functionOverrides: data?.functionOverrides
    });

    const bundle = await bundleFixtures.available({
      functionOid: func.oid,
      overrides: data?.bundleOverrides
    });

    const deployment = await defaultDeployment({
      functionOid: func.oid,
      runtimeOid: func.runtime!.oid,
      functionBundleOid: bundle.oid,
      overrides: {
        status: FunctionDeploymentStatus.succeeded,
        ...data?.deploymentOverrides
      }
    });

    return db.functionDeployment.findUniqueOrThrow({
      where: { oid: deployment.oid },
      include: {
        function: { include: { tenant: true } },
        runtime: { include: { provider: true } },
        functionBundle: true
      }
    }) as Promise<
      FunctionDeployment & {
        function: FunctionModel & { tenant: Tenant };
        runtime: Runtime & { provider: Provider };
        functionBundle: FunctionBundle;
      }
    >;
  };

  const failed = async (data?: {
    tenantOverrides?: Partial<Tenant>;
    functionOverrides?: Partial<FunctionModel>;
    deploymentOverrides?: Partial<FunctionDeployment>;
    errorCode?: string;
    errorMessage?: string;
  }): Promise<
    FunctionDeployment & {
      function: FunctionModel & { tenant: Tenant };
      runtime: Runtime & { provider: Provider };
    }
  > => {
    const func = await functionFixtures.withTenantAndRuntime({
      tenantOverrides: data?.tenantOverrides,
      functionOverrides: data?.functionOverrides
    });

    const deployment = await defaultDeployment({
      functionOid: func.oid,
      runtimeOid: func.runtime!.oid,
      overrides: {
        status: FunctionDeploymentStatus.failed,
        errorCode: data?.errorCode ?? 'BUILD_FAILED',
        errorMessage: data?.errorMessage ?? 'Build process failed',
        ...data?.deploymentOverrides
      }
    });

    return db.functionDeployment.findUniqueOrThrow({
      where: { oid: deployment.oid },
      include: {
        function: { include: { tenant: true } },
        runtime: { include: { provider: true } }
      }
    }) as Promise<
      FunctionDeployment & {
        function: FunctionModel & { tenant: Tenant };
        runtime: Runtime & { provider: Provider };
      }
    >;
  };

  return {
    default: defaultDeployment,
    pending,
    succeeded,
    failed
  };
};

import type {
  PrismaClient,
  FunctionDeploymentStep
} from '../../../prisma/generated/client';
import {
  FunctionDeploymentStepStatus,
  FunctionDeploymentStepType
} from '../../../prisma/generated/client';
import { getId } from '../../id';
import { defineFactory } from '@lowerdeck/testing-tools';

export const FunctionDeploymentStepFixtures = (db: PrismaClient) => {
  const defaultStep = async (data: {
    functionDeploymentOid: bigint;
    overrides?: Partial<FunctionDeploymentStep>;
  }): Promise<FunctionDeploymentStep> => {
    const { oid, id } = getId('functionDeploymentStep');

    const factory = defineFactory<FunctionDeploymentStep>(
      {
        oid,
        id,
        status: data.overrides?.status ?? FunctionDeploymentStepStatus.pending,
        type: data.overrides?.type ?? FunctionDeploymentStepType.deploy,
        name: data.overrides?.name ?? 'Deploy Step',
        output: data.overrides?.output ?? '',
        functionDeploymentOid: data.functionDeploymentOid,
        startedAt: data.overrides?.startedAt ?? null,
        endedAt: data.overrides?.endedAt ?? null
      } as FunctionDeploymentStep,
      {
        persist: value => db.functionDeploymentStep.create({ data: value })
      }
    );

    return factory.create(data.overrides ?? {});
  };

  const succeeded = async (data: {
    functionDeploymentOid: bigint;
    output?: string;
    overrides?: Partial<FunctionDeploymentStep>;
  }): Promise<FunctionDeploymentStep> => {
    const now = new Date();
    return defaultStep({
      functionDeploymentOid: data.functionDeploymentOid,
      overrides: {
        status: FunctionDeploymentStepStatus.succeeded,
        output: data.output ?? 'Step completed successfully',
        startedAt: new Date(now.getTime() - 5000),
        endedAt: now,
        ...data.overrides
      }
    });
  };

  const failed = async (data: {
    functionDeploymentOid: bigint;
    output?: string;
    overrides?: Partial<FunctionDeploymentStep>;
  }): Promise<FunctionDeploymentStep> => {
    const now = new Date();
    return defaultStep({
      functionDeploymentOid: data.functionDeploymentOid,
      overrides: {
        status: FunctionDeploymentStepStatus.failed,
        output: data.output ?? 'Step failed with error',
        startedAt: new Date(now.getTime() - 3000),
        endedAt: now,
        ...data.overrides
      }
    });
  };

  const running = async (data: {
    functionDeploymentOid: bigint;
    overrides?: Partial<FunctionDeploymentStep>;
  }): Promise<FunctionDeploymentStep> =>
    defaultStep({
      functionDeploymentOid: data.functionDeploymentOid,
      overrides: {
        status: FunctionDeploymentStepStatus.running,
        startedAt: new Date(),
        ...data.overrides
      }
    });

  return {
    default: defaultStep,
    succeeded,
    failed,
    running
  };
};

