import { functionBayRuntimeSpec } from '@function-bay/types';
import { Paginator } from '@lowerdeck/pagination';
import { createValidator, v, type ValidatorOptions } from '@lowerdeck/validation';
import { functionDeploymentPresenter, functionDeploymentStepPresenter } from '../presenters';
import { functionDeploymentService } from '../services';
import { app } from './_app';
import { functionApp } from './function';

export let functionDeploymentApp = functionApp.use(async ctx => {
  let functionDeploymentId = ctx.body.functionDeploymentId;
  if (!functionDeploymentId) throw new Error('Function Deployment ID is required');

  let deployment = await functionDeploymentService.getFunctionDeploymentById({
    id: functionDeploymentId,
    function: ctx.function
  });

  return { deployment };
});

let longString = createValidator<string, ValidatorOptions<string>>('string', (opts, value) => {
  if (typeof value != 'string') {
    return {
      success: false,
      errors: [
        {
          code: 'invalid_type',
          message: opts.message ?? `Invalid input, expected string, received ${typeof value}`,
          received: typeof value,
          expected: 'string'
        }
      ]
    };
  }

  if (value.length > 50_000_000) {
    return {
      success: false,
      errors: [
        {
          code: 'max_length',
          message: 'Input is too long'
        }
      ]
    };
  }

  return { success: true, value };
});

export let functionDeploymentController = app.controller({
  create: functionApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        functionId: v.string(),

        name: v.string(),

        runtime: functionBayRuntimeSpec,

        config: v.object({
          memorySizeMb: v.number(),
          timeoutSeconds: v.number()
        }),

        env: v.record(v.string()),
        files: v.array(
          v.object({
            filename: v.string(),
            content: longString(),
            encoding: v.optional(v.enumOf(['utf-8', 'base64']))
          })
        )
      })
    )
    .do(async ctx => {
      let version = await functionDeploymentService.createFunctionDeployment({
        function: ctx.function,
        tenant: ctx.tenant,
        input: {
          name: ctx.input.name,
          env: ctx.input.env,
          files: ctx.input.files,
          runtime: ctx.input.runtime,
          config: ctx.input.config
        }
      });
      return functionDeploymentPresenter(version);
    }),

  list: functionApp
    .handler()
    .input(
      Paginator.validate(
        v.object({
          functionId: v.string(),
          tenantId: v.string()
        })
      )
    )
    .do(async ctx => {
      let paginator = await functionDeploymentService.listFunctionDeployments({
        function: ctx.function
      });

      let list = await paginator.run(ctx.input);

      return Paginator.presentLight(list, functionDeploymentPresenter);
    }),

  get: functionDeploymentApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        functionId: v.string(),
        functionDeploymentId: v.string()
      })
    )
    .do(async ctx => functionDeploymentPresenter(ctx.deployment)),

  getOutput: functionDeploymentApp
    .handler()
    .input(
      v.object({
        tenantId: v.string(),
        functionId: v.string(),
        functionDeploymentId: v.string()
      })
    )
    .do(async ctx => {
      let output = await functionDeploymentService.getFunctionDeploymentOutput({
        deployment: ctx.deployment
      });

      return output.steps.map(functionDeploymentStepPresenter);
    })
});

import type { FunctionBayRuntimeSpec } from '@function-bay/types';
import { notFoundError, ServiceError } from '@lowerdeck/error';
import { generatePlainId } from '@lowerdeck/id';
import { Paginator } from '@lowerdeck/pagination';
import { Service } from '@lowerdeck/service';
import type { Function, FunctionDeployment, Tenant } from '../../prisma/generated/client';
import { db } from '../db';
import { encryption } from '../encryption';
import { forge } from '../forge';
import { ID, snowflake } from '../id';
import { defaultProvider } from '../providers';
import { startBuildQueue } from '../queues/build';

let include = {
  function: {
    include: {
      currentVersion: true
    }
  },
  runtime: {
    include: {
      provider: true
    }
  },
  functionVersion: true,
  steps: true
};

class functionDeploymentServiceImpl {
  async createFunctionDeployment(d: {
    function: Function;
    tenant: Tenant;
    input: {
      name: string;
      env: Record<string, string>;
      files: {
        filename: string;
        content: string;
        encoding?: 'utf-8' | 'base64';
      }[];
      runtime: FunctionBayRuntimeSpec;
      config: PrismaJson.FunctionConfiguration;
    };
  }) {
    let providerRuntime = await defaultProvider.getRuntime(d.input.runtime);

    let id = await ID.generateId('functionDeployment');

    let deployment = await db.functionDeployment.create({
      data: {
        oid: snowflake.nextId(),
        id,
        status: 'pending',
        identifier: generatePlainId(12),
        name: d.input.name,
        configuration: d.input.config,
        runtimeOid: providerRuntime.runtime.oid,
        functionOid: d.function.oid,

        steps: {
          create: [
            {
              oid: snowflake.nextId(),
              id: await ID.generateId('functionDeploymentStep'),
              status: 'pending',
              type: 'deploy',
              name: 'Deploy Function',
              output: ''
            }
          ]
        },

        encryptedEnvironmentVariables: await encryption.encrypt({
          secret: [REDACTED],
          entityId: id
        })
      },
      include
    });

    await startBuildQueue.add({ deploymentId: deployment.id, files: d.input.files });

    return deployment;
  }

  async getFunctionDeploymentById(d: { id: string; function: Function }) {
    let functionDeployment = await db.functionDeployment.findFirst({
      where: {
        OR: [{ id: d.id }, { identifier: d.id }],
        functionOid: d.function.oid
      },
      include
    });
    if (!functionDeployment) throw new ServiceError(notFoundError('function.deployment'));
    return functionDeployment;
  }

  async getFunctionDeploymentOutput(d: { deployment: FunctionDeployment }) {
    let func = await db.function.findFirstOrThrow({
      where: {
        oid: d.deployment.functionOid
      },
      include: {
        tenant: true
      }
    });

    let steps = await db.functionDeploymentStep.findMany({
      where: {
        functionDeploymentOid: d.deployment.oid
      }
    });

    let forgeLogs = d.deployment.forgeRunId
      ? await forge.workflowRun.getOutput({
          tenantId: func.tenant.identifier,
          workflowRunId: d.deployment.forgeRunId,
          workflowId: d.deployment.forgeWorkflowId!
        })
      : null;

    return {
      steps: [
        ...(forgeLogs ?? []).map(s => ({
          id: `forge#${s.step.id}`,
          name: s.step.name,
          type: 'build' as const,
          status: s.step.status,
          logs: s.logs,
          createdAt: s.step.createdAt,
          startedAt: s.step.startedAt,
          endedAt: s.step.endedAt
        })),

        ...steps.map(s => ({
          id: `function-bay#${s.id}`,
          name: s.name,
          type: s.type,
          status: s.status,

          createdAt: s.createdAt,
          startedAt: s.startedAt,
          endedAt: s.endedAt,

          logs: !s.output
            ? []
            : s.output
                .split('\n')
                .map(line => {
                  if (!line.startsWith('[')) return undefined!;
                  let [ts, message] = JSON.parse(line);

                  return {
                    timestamp: ts,
                    message
                  };
                })
                .filter(Boolean)
        }))
      ]
    };
  }

  async listFunctionDeployments(d: { function: Function }) {
    return Paginator.create(({ prisma }) =>
      prisma(
        async opts =>
          await db.functionDeployment.findMany({
            ...opts,
            where: {
              functionOid: d.function.oid
            },
            include
          })
      )
    );
  }
}

export let functionDeploymentService = Service.create(
  'functionDeploymentService',
  () => new functionDeploymentServiceImpl()
).build();

import type {
  Function,
  FunctionDeployment,
  FunctionDeploymentStep,
  FunctionDeploymentStepStatus,
  FunctionDeploymentStepType,
  FunctionVersion,
  Provider,
  Runtime
} from '../../prisma/generated/client';
import { functionPresenter } from './function';
import { functionVersionPresenter } from './functionVersion';
import { runtimePresenter } from './runtime';

export let functionDeploymentPresenter = (
  deployment: FunctionDeployment & {
    function: Function & {
      currentVersion: FunctionVersion | null;
    };
    runtime: Runtime & {
      provider: Provider;
    };
    functionVersion: FunctionVersion | null;
    steps: FunctionDeploymentStep[];
  }
) => ({
  object: 'function_bay#function.deployment',

  id: deployment.id,
  status: deployment.status,

  error: deployment.errorCode
    ? {
        code: deployment.errorCode,
        message: deployment.errorMessage ?? deployment.errorCode
      }
    : null,

  identifier: deployment.identifier,
  name: deployment.name,

  configuration: deployment.configuration,

  function: functionPresenter(deployment.function),
  runtime: runtimePresenter(deployment.runtime),
  version: deployment.functionVersion
    ? functionVersionPresenter({
        ...deployment.functionVersion,
        function: deployment.function,
        runtime: deployment.runtime
      })
    : null,

  createdAt: deployment.createdAt
});

export let functionDeploymentStepPresenter = (step: {
  id: string;
  name: string;
  type: FunctionDeploymentStepType | 'build';
  status: FunctionDeploymentStepStatus;
  logs: { timestamp: number; message: string }[];
  createdAt: Date;
  startedAt: Date | null;
  endedAt: Date | null;
}) => ({
  object: 'function_bay#function.deployment.step',

  id: step.id,
  status: step.status,
  name: step.name,

  logs: step.logs,
  type: step.type,

  createdAt: step.createdAt,
  startedAt: step.startedAt,
  endedAt: step.endedAt
});

# Function Bay

Function Bay is a serverless function deployment and orchestration service that wraps cloud function providers (like AWS Lambda) to provide a unified API for deploying, versioning, invoking, and managing serverless functions.

## Features

- **Multi-Provider Support**: Currently supports AWS Lambda with extensible architecture for additional providers
- **Function Management**: Define, version, and manage serverless functions with configurations
- **Deployment Orchestration**: Automated deployment workflows with build tracking and logging via Forge
- **Runtime Support**: Multiple runtime environments including Node.js, Python, Ruby, and Java
- **Function Invocation**: Direct function invocation with payload support and detailed logging
- **Version Control**: Track and manage different versions of your functions
- **Tenant Isolation**: Multi-tenant architecture for isolated projects
- **Configuration Management**: Memory, timeout, and environment variable configuration per deployment

