  },
  env: {
    NODE_ENV: 'production',
    API_KEY: '[REDACTED]',
  },
  files: [
    {
      filename: 'index.js',
      content: `
        export const handler = async (event) => {
          return {
            statusCode: 200,
            body: JSON.stringify({ message: 'Hello from Function Bay!' }),
          };
        };
      `,
      encoding: 'utf-8',
    },
    {
      filename: 'package.json',
      content: JSON.stringify({
